const CORES_IDENTIDADE = {
  sienna: "139 74 43",
  ardosia: "74 97 120",
  musgo: "95 107 58",
  cafe: "74 52 42",
  /* Carvão — só pro selo/card de Sábado no calendário semanal do
     Dashboard (2026-09-17), não faz parte da rotação de cor das oficinas
     (por isso fora de CORES_ORDEM, que corOficina() usa pra distribuir
     cor entre oficinas — incluir aqui mudaria a cor que oficinas já
     cadastradas recebem). */
  carvao: "38 38 36",
};
const CORES_ORDEM = ["sienna", "ardosia", "musgo", "cafe"];
const TURMA_COR = { "ter-1830": "sienna", "qua-1630": "ardosia", "qui-1430": "musgo", "qui-1830": "cafe" };
/* Mesmas 4 turmas, chave por rótulo em vez de id — usado onde o dado só
   tem o texto (ex: cadastro de aluno), não o id de TURMAS_DIAS. */
const TURMA_LABEL_COR = { "Terça 18:30": "sienna", "Quarta 16:30": "ardosia", "Quinta 14:30": "musgo", "Quinta 18:30": "cafe" };
/* Ponte entre os dois formatos de turma que convivem no app (id, usado
   por `vagasPorTurma`/`TURMAS_DIAS`, vs. rótulo em texto, usado só por
   `alunosLista`/`TURMA_LABEL_COR`) — necessária a partir da edição de
   aluno (2026-09-18: "mudar a turma" precisa funcionar pros dois formatos
   de onde `AlunoDetalhe` pode ter sido aberto, ver `salvarEdicaoAluno`).
   Chaves escritas à mão, não derivadas de `dia`/`hora` por concatenação —
   mais seguro que bater exatamente com `TURMA_LABEL_COR` por acidente de
   formatação de string. */
const TURMA_ID_PARA_LABEL = { "ter-1830": "Terça 18:30", "qua-1630": "Quarta 16:30", "qui-1430": "Quinta 14:30", "qui-1830": "Quinta 18:30" };
const TURMA_LABEL_PARA_ID = Object.fromEntries(Object.entries(TURMA_ID_PARA_LABEL).map(([id, label]) => [label, id]));

function rgbCor(corKey, alpha) {
  const rgb = CORES_IDENTIDADE[corKey] || CORES_IDENTIDADE.sienna;
  return alpha === undefined ? `rgb(${rgb})` : `rgb(${rgb} / ${alpha})`;
}
function corTurma(turmaId) { return TURMA_COR[turmaId] || "sienna"; }
function turmaPorId(turmaId) {
  for (const d of TURMAS_DIAS) {
    const t = d.turmas.find((t) => t.id === turmaId);
    if (t) return t;
  }
  return null;
}
/* Rampa de cor incandescente por temperatura (vermelho escuro -> laranja ->
   amarelo-claro, a mesma progressão de corpo negro que se vê num forno/forja
   de verdade) — só usada no brilho pulsante do card do forno no Dashboard,
   não é cor de identidade visual do app. Interpola entre pontos fixos em vez
   de fórmula de temperatura de cor real (sem necessidade de precisão
   científica aqui, só leitura visual crível). */
function corIncandescente(temp) {
  const pontos = [
    { t: 100, rgb: [58, 30, 22] },
    { t: 500, rgb: [130, 30, 14] },
    { t: 700, rgb: [199, 51, 18] },
    { t: 900, rgb: [230, 96, 15] },
    { t: 1100, rgb: [244, 154, 28] },
    { t: 1300, rgb: [255, 214, 120] },
  ];
  if (temp <= pontos[0].t) return pontos[0].rgb.join(" ");
  for (let i = 1; i < pontos.length; i++) {
    if (temp <= pontos[i].t) {
      const a = pontos[i - 1], b = pontos[i];
      const f = (temp - a.t) / (b.t - a.t);
      return a.rgb.map((v, idx) => Math.round(v + (b.rgb[idx] - v) * f)).join(" ");
    }
  }
  return pontos[pontos.length - 1].rgb.join(" ");
}
/* Abaixo disso o forno ainda não "brilha" de verdade (calor visível só
   começa por volta do vermelho-escuro) — pedido do Diego: forno frio ou
   desligado usa azul com menos efeito em vez da rampa incandescente. */
const TEMP_FORNO_QUENTE = 250;
const COR_FORNO_FRIO = "68 121 173";
function corOficina(oficina) {
  let h = 0;
  for (let i = 0; i < oficina.id.length; i++) h = (h * 31 + oficina.id.charCodeAt(i)) | 0;
  return CORES_ORDEM[Math.abs(h) % CORES_ORDEM.length];
}
/* Estilo inline (não classe Tailwind) porque a cor varia em tempo de
   execução por turma/oficina — o scanner JIT do Tailwind (CDN) só gera CSS
   pra classes literais no código-fonte, não pra strings montadas em JS. */
function estiloVidroTingido(corKey, alphaTopo = 0.45, alphaBase = 0.22) {
  return {
    background: `linear-gradient(180deg, ${rgbCor(corKey, alphaTopo)}, ${rgbCor(corKey, alphaBase)})`,
    borderColor: rgbCor(corKey, alphaTopo),
    color: "#fff",
    textShadow: "0 1px 2px rgba(0,0,0,0.35)",
  };
}
/* Tom quente embutido no próprio gradiente (não branco puro) — antes
   dependia só do que estivesse atrás pra colorir o vidro, e dois cards em
   posições diferentes da página (pegando pontos diferentes das manchas de
   fundo) liam como dois materiais diferentes (achado do Diego: "o
   tratamento desses cards estão diferentes"). Com uma base própria, todo
   card de vidro tem a mesma qualidade mínima consistente, e a mancha atrás
   só soma variação, não é mais a única fonte da cor. */
const VIDRO_CARD = "rounded-[26px] border border-white/80 bg-gradient-to-b from-[#FEFBF6]/90 to-[#FAF2E6]/65 shadow-[inset_0_1.5px_0_rgba(255,255,255,0.85),0_16px_32px_-10px_rgba(59,56,51,0.2),0_2px_6px_rgba(59,56,51,0.07)] backdrop-blur-2xl backdrop-saturate-150";
/* Sem backdrop-blur aqui de propósito — pills pequenas (dia/horário)
   coladas lado a lado com blur cada uma causavam uma costura/risco visual
   passageiro entre elas ao re-renderizar (achado do Diego: "esse risco
   atrás de Qua e Qui... depois de alguns segundos some" — artefato de
   composição de GPU do navegador com muitos elementos com blur adjacentes).
   O gradiente+borda já dá a leitura de vidro numa pill pequena; blur real
   fica reservado pros cards grandes, onde faz diferença de verdade. */
const VIDRO_PILL = "rounded-full border shadow-[inset_0_1.5px_0_rgba(255,255,255,0.6)]";
/* "Sólido" != chapado: mesmo o estado de ação/selecionado ganha gradiente +
   brilho superior + sombra, a mesma qualidade de profundidade do vidro, só
   sem o blur/translucidez — nunca um preenchimento de cor plana lisa. */
const ACCENT_SOLIDO = "border border-white/40 bg-gradient-to-b from-[rgba(214,110,44,0.82)] to-[rgba(194,65,12,0.72)] text-white shadow-[inset_0_1.5px_0_rgba(255,255,255,0.4),0_3px_10px_-2px_rgba(194,65,12,0.4)] backdrop-blur-xl backdrop-saturate-150 transition hover:brightness-105 active:brightness-95";
/* Pill neutra pros dias sem turma (Seg/Sex/Sáb/Dom) — muda mas legível,
   não texto quase invisível direto sobre o fundo colorido. Opacidade
   subida de 25% pra 65% (2026-09-17): único uso é a aba de dia em Turmas,
   que agora fica sobre a foto de mesclagem de argila (bem mais "barulhenta"
   que as manchas suaves de antes) — achado do Diego: "os botões estão
   fracos parecem estar por trás e não na frente do fundo". */
const VIDRO_PILL_NEUTRO = "rounded-full border border-white/60 bg-white/65 text-[var(--ink-soft)] backdrop-blur-md";

/* Fundos de mesclagem de argila por cor de identidade (fase Turmas,
   2026-09-17) -- fotos reais que o Diego mandou ("vc nao consegue usar a
   foto q enviei como fundo?"), nao recriacoes. Uma por cor ja estabelecida
   em CORES_IDENTIDADE, pedido explicito: "qro q cada dia seja uma cor
   diferente, quarta azul e quinta o fundo verde" -- azul bate com ardosia
   (ja era a cor de Quarta) e verde com musgo (ja era a cor de Quinta
   14:30), entao o mapeamento reaproveita o sistema de cor por turma que ja
   existia, so aplicado tambem ao fundo. Sem foto pra "cafe" ainda -- dias
   sem turma (Seg/Sex/Sab/Dom) ou sem imagem correspondente ficam sem fundo
   especial (cai no --cream normal). Cada imagem redimensionada (941x1672
   -> 480px de largura) e comprimida em JPEG (~75-97KB) pra caber embutida
   em base64 no artifact -- PNGs originais tinham ~3MB cada, grandes demais
   pra esse arquivo unico. */
const FUNDOS_ARGILA = {
  carvao: "data:image/jpeg;base64,",
  sienna: "data:image/jpeg;base64,",
  ardosia: "data:image/jpeg;base64,",
  musgo: "data:image/jpeg;base64,",
};
/* Fundo de foto com parallax — extraído do que era só de Turmas
   (2026-09-17) pra virar reutilizável: o Diego pediu o mesmo tratamento
   em Oficinas, "o msm padrao das turmas, porem com esse fundo" (foto
   carvão, preto-e-branco). Mesma receita: dentro do fluxo normal (não
   fixed/position:fixed — teria sempre o mesmo recorte), repeat-y,
   parallax a 35% da velocidade do scroll via ref (sem re-render),
   degradê cream só no topo pro título respirar. `cor` é uma chave de
   FUNDOS_ARGILA; se não existir, não renderiza nada. */
function FundoArgilaParallax({ cor }) {
  const imgFundo = cor && FUNDOS_ARGILA[cor];
  const fundoRef = useRef(null);
  /* `position:fixed` (não mais `absolute`) — achado do Diego (2026-09-17):
     "qnd uso scroll ele da uma puladinha e nao fica parado o fundo para
     q eu percorra sobre ele". Com `absolute`, o container em si já rolava
     JUNTO com a página (100% da velocidade, por estar no fluxo normal) e
     o JS só compensava por cima deslocando backgroundPositionY em sentido
     contrário — duas fontes de movimento tentando se cancelar quase por
     inteiro. Em scroll rápido (fling de trackpad/mobile) o navegador
     processa o movimento do container mais rápido do que o
     requestAnimationFrame consegue reaplicar a compensação, e aparece
     como um "pulinho" — as duas animações saem de sincronia por um
     instante. Com `fixed`, o container não tem movimento nativo NENHUM
     (0%) — o `backgroundPositionY` via JS vira a ÚNICA fonte de
     movimento, sem nada pra dessincronizar. Fórmula também simplificou:
     não precisa mais compensar 100% de movimento do container, só aplicar
     a velocidade direto (`scrollY * VELOCIDADE`, sem o `1 -`). */
  useEffect(() => {
    if (!imgFundo) return;
    const VELOCIDADE = 0.35;
    let raf = null;
    function aplicar() {
      raf = null;
      if (fundoRef.current) fundoRef.current.style.backgroundPositionY = `${window.scrollY * VELOCIDADE}px`;
    }
    function onScroll() {
      if (raf === null) raf = requestAnimationFrame(aplicar);
    }
    window.addEventListener("scroll", onScroll, { passive: true });
    aplicar();
    return () => {
      window.removeEventListener("scroll", onScroll);
      if (raf !== null) cancelAnimationFrame(raf);
    };
  }, [imgFundo]);
  if (!imgFundo) return null;
  /* `fixed inset-0` também resolve a "borda lateral" (achado anterior do
     Diego) de um jeito mais robusto que a margem negativa que eu tinha
     posto — `fixed` ignora completamente o padding/offset de qualquer
     ancestral (inclusive a sidebar de 128px no desktop), preenche o
     viewport inteiro sempre. Isso faz esse fundo voltar a competir por
     empilhamento com `<aside>`/`<header>` do jeito que o `ManchasFundo`
     global competia (mesma causa raiz de antes) — por isso `<aside>` e o
     `<header>` mobile ganharam `z-10` explícito (ver mais abaixo), pra
     sempre pintar por cima independente da ordem no DOM. */
  return (
    <div className="pointer-events-none fixed inset-0 overflow-hidden" aria-hidden="true">
      <div ref={fundoRef} className="absolute inset-0" style={{ backgroundImage: `url(${imgFundo})`, backgroundSize: "100% auto", backgroundRepeat: "repeat-y", backgroundPosition: "center top" }} />
      <div className="absolute inset-x-0 top-0 h-36 bg-gradient-to-b from-[var(--cream)] via-[var(--cream)]/75 to-transparent" />
    </div>
  );
}
/* Foto dedicada do cabecalho mobile (2026-09-17) -- o Diego mandou uma
   imagem nova especificamente pra essa barra ("troque a imagem do
   cabecalho por essa"), mais escura/preta que FUNDOS_ARGILA.carvao (que
   continua em uso em Oficinas e no card de Sabado) -- por isso uma
   constante separada, nao substitui a existente. */
const FUNDO_CABECALHO_SRC = "data:image/jpeg;base64,";
function ManchasFundo({ tela }) {
  /* Do tamanho do viewport inteiro (fixed), não de um "quadro" pequeno —
     precisam ser grandes/fortes o bastante pra ler em tela cheia, inclusive
     driblando a sidebar desktop opaca (128px) que cobre manchas encostadas
     na borda esquerda. Testado e recalibrado depois que a primeira versão
     (raios de 176-224px) ficou praticamente invisível em desktop. */
  /* As 3 manchas ficam escalonadas verticalmente (topo/meio/rodapé), nunca
     duas na mesma faixa — 2 versões atrás, sienna e ardósia ficaram as duas
     coladas no topo, se sobrepondo e derretendo pra um marrom-acinzentado
     escuro/embaçado bem em cima do cabeçalho (achado real do Diego,
     confirmado por screenshot: "essa área está toda apagada"). */
  /* Mobile-first de propósito (regra do projeto: pensar no celular
     primeiro) — as manchas eram dimensionadas pra caber bem em desktop
     (md:) e isso as deixava grandes/fortes demais num viewport de 375px,
     cobrindo o cabeçalho inteiro com a mancha no seu ponto mais forte.
     Base pequena, cresce só a partir de md. */
  /* Turmas ganhou um fundo diferente (2026-09-17): a foto real de
     mesclagem de argila que o Diego mandou, não as manchas — pedido
     explícito e escopado só a essa tela ("serao usadas como fundo nas
     turmas"). Essa foto NÃO mora aqui (componente fica de fora quando
     tela==="turmas") — o Diego pediu pra rolar "através" da imagem
     conforme desce a lista ("conforme eu desça no scroll eu percorra por
     ela"), o que position:fixed nunca faz (fica sempre preso ao viewport,
     mesmo recorte o tempo todo). Por isso o fundo da Turmas vive dentro
     do próprio fluxo de rolagem do componente `Turmas`, não aqui. */
  if (tela === "turmas") return null;
  return (
    <div className="pointer-events-none fixed inset-0 z-0 overflow-hidden" aria-hidden="true">
      <div className="absolute -right-16 top-24 h-56 w-56 rounded-full blur-3xl md:-right-32 md:top-[-8%] md:h-[420px] md:w-[420px]" style={{ background: rgbCor("sienna", 0.24) }} />
      <div className="absolute -left-14 top-[42%] h-52 w-52 rounded-full blur-3xl md:-left-24 md:top-[38%] md:h-[380px] md:w-[380px]" style={{ background: rgbCor("ardosia", 0.2) }} />
      <div className="absolute -right-14 top-[76%] h-56 w-56 rounded-full blur-3xl md:-right-24 md:top-[72%] md:h-[400px] md:w-[400px]" style={{ background: rgbCor("musgo", 0.22) }} />
    </div>
  );
}

