const FONT_DISPLAY = { fontFamily: "var(--font-display)" };

function Card({ className = "", children }) {
  return <div className={"min-w-0 rounded-2xl border border-[var(--line)] bg-white shadow-sm " + className}>{children}</div>;
}
function Badge({ tone = "neutral", children }) {
  const tones = {
    success: "bg-emerald-50 text-emerald-700", warning: "bg-amber-100 text-amber-700",
    danger: "bg-rose-100 text-rose-600",
    info: "border border-[var(--ink)] text-[var(--ink)]",
    neutral: "bg-[var(--cream-soft)] text-[var(--ink-soft)]",
  };
  return <span className={"inline-flex max-w-full items-center whitespace-normal break-words rounded-full px-2.5 py-1 text-xs font-medium " + tones[tone]}>{children}</span>;
}
/* `anelCor` (2026-09-17, feature de vaga provisória): contorno colorido
   opcional em volta do avatar, cor da turma de ORIGEM de quem está de
   visita numa turma diferente — achado do Diego vendo a Ju Pita movida:
   "faltou a borda do card dela da cor original", a etiqueta de texto
   sozinha (ver linha de aluno em Turmas) não estava chamando atenção o
   suficiente. `boxShadow` em vez de `ring-*` do Tailwind porque a cor
   varia em tempo de execução por turma (mesmo motivo de `estiloVidroTingido`
   não usar classe fixa). */
function Avatar({ nome, size = 40, stacked, anelCor }) {
  const iniciais = nome ? nome.split(" ").slice(0, 2).map((p) => p[0]?.toUpperCase()).join("") : "?";
  return (
    <div
      style={{
        width: size, height: size, fontSize: Math.max(9, size * 0.36),
        boxShadow: anelCor ? `0 0 0 2.5px ${anelCor}` : undefined,
      }}
      className={"flex items-center justify-center overflow-hidden rounded-full bg-[var(--ink)] text-[var(--cream)] font-medium shrink-0 leading-none " + (stacked ? "ring-2 ring-white" : "")}
    >
      {iniciais}
    </div>
  );
}
function Toggle({ checked, onChange, title }) {
  return (
    <button
      onClick={onChange}
      title={title}
      aria-label={title}
      aria-pressed={checked}
      className={"relative h-6 w-11 shrink-0 rounded-full transition-colors " + (checked ? "bg-emerald-500" : "bg-[var(--line)]")}
    >
      <span className={"absolute left-0.5 top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform " + (checked ? "translate-x-5" : "translate-x-0")} />
    </button>
  );
}
/* Logotipo real da marca (wordmark "MTCST") -- era uma imagem recortada da
   arte que o Diego mandou (ver historico no CLAUDE.md), trocado por TEXTO
   de verdade em 2026-09-17: "a fonte do logo e a Bebas Neue, refaca o
   logo usando ela". Muito mais robusto que a imagem -- a versao em PNG
   tinha um bug real de transparencia (quantize() perdendo o canal alpha
   de um jeito que so apareceu ao tentar deixar o logo branco sobre o
   fundo escuro do cabecalho; PIL e o navegador discordavam sobre o alpha
   do mesmo arquivo, nunca totalmente diagnosticado -- texto elimina o
   problema de raiz, cor e so `color`/`currentColor`, sem canal alpha
   nenhum envolvido). `uppercase` nao e decorativo aqui -- Bebas Neue nao
   tem uma forma minuscula visualmente distinta, e desenhada pra caixa
   alta. */
function LogoMark({ className, style }) {
  return <span className={"font-bold uppercase leading-none tracking-wide " + (className || "text-xl text-[var(--ink)]")} style={{ fontFamily: "'Bebas Neue', var(--font-display)", ...style }}>MTCST</span>;
}
function Modal({ children, onClose }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />
      <div className="relative w-full max-w-sm rounded-3xl border border-[var(--line)] bg-white p-5 shadow-xl animate-in">{children}</div>
    </div>
  );
}

