export default function AtelieDemo() {
  const [tela, setTela] = useState("dashboard");
  const [menuAberto, setMenuAberto] = useState(false);
  const [toast, setToast] = useState(null);
  const [fornadas, setFornadas] = useState(fornadasIniciais);
  const [rascunho, setRascunho] = useState(null); // config pré-preenchida ao "Duplicar"
  const [fornoAlvo, setFornoAlvo] = useState(FORNOS[0].id); // pra qual forno a Nova Fornada em andamento é
  const [modalConflito, setModalConflito] = useState(null); // fornoId em conflito, ou null
  const [oficinas, setOficinas] = useState(oficinasIniciais);
  const [oficinaAbertaId, setOficinaAbertaId] = useState(null);
  /* Criar/editar oficina (2026-09-18) — auditoria de autonomia: o "+"
     (Nova oficina) e o "Editar oficina" não tinham NENHUM `onClick`,
     clicar não fazia nada. `modalOficina` guarda `"nova"` (formulário em
     branco) ou a própria oficina (formulário preenchido, editando) — o
     mesmo `ModalOficina` serve pros dois modos. */
  const [modalOficina, setModalOficina] = useState(null);
  function criarOficina(dados) {
    const nova = {
      id: "o" + Date.now(), status: "Agendada", statusPecas: "secagem",
      receita: [], observacoes: "",
      ...dados,
      participantes: Array.from({ length: dados.vagas }, (_, i) => ({ numero: i + 1, nome: null })),
    };
    setOficinas((os) => [nova, ...os]);
    notificar(`Oficina "${dados.nome}" criada.`);
    setModalOficina(null);
  }
  /* Editar preserva `participantes`/`receita`/`statusPecas` (fora do
     formulário) — só ajusta o array de vagas se `vagas` mudou. Encolher
     nunca apaga uma vaga OCUPADA (protege dado real de participante já
     inscrito); só remove vagas vazias do fim, e recusa (mantém o número
     antigo) se não houver vazias suficientes pra encolher até o pedido. */
  function editarOficina(id, dados) {
    setOficinas((os) => os.map((o) => {
      if (o.id !== id) return o;
      let participantes = o.participantes;
      let vagasFinal = dados.vagas;
      if (vagasFinal > o.vagas) {
        const extras = Array.from({ length: vagasFinal - o.vagas }, (_, i) => ({ numero: o.vagas + i + 1, nome: null }));
        participantes = [...o.participantes, ...extras];
      } else if (vagasFinal < o.vagas) {
        const removeriaOcupada = o.participantes.slice(vagasFinal).some((p) => p.nome);
        if (removeriaOcupada) {
          notificar("Não dá pra reduzir vagas abaixo do número de participantes já inscritos.");
          vagasFinal = o.vagas;
        } else {
          participantes = o.participantes.slice(0, vagasFinal);
        }
      }
      return { ...o, ...dados, vagas: vagasFinal, participantes };
    }));
    notificar("Oficina atualizada.");
    setModalOficina(null);
  }

  function notificar(msg) { setToast(msg); setTimeout(() => setToast(null), 2200); }

  function fornadaAtivaDoForno(fornoId) {
    return fornadas.find((f) => f.status === "andamento" && f.fornoId === fornoId) || null;
  }

  function abrirNovaFornada(base, fornoId) {
    setRascunho(base || null);
    setFornoAlvo(fornoId || base?.fornoId || FORNOS[0].id);
    setTela("fornoNova");
    window.scrollTo(0, 0);
  }

  function cliqueNovaFornada(fornoId) {
    if (fornadaAtivaDoForno(fornoId)) setModalConflito(fornoId);
    else abrirNovaFornada(null, fornoId);
  }

  function confirmarSalvarEIniciarNova() {
    const conflitante = fornadaAtivaDoForno(modalConflito);
    setFornadas((fs) => fs.map((f) => f.id === conflitante.id ? { ...f, status: "interrompida", finalizadoEm: new Date() } : f));
    const fornoId = modalConflito;
    setModalConflito(null);
    notificar("Fornada atual salva no histórico como Interrompida.");
    abrirNovaFornada(null, fornoId);
  }

  function iniciarFornada(config) {
    const nova = {
      id: "f" + Date.now(), fornoId: fornoAlvo, tipo: config.tipo, tipoDescricao: config.tipoDescricao,
      categorias: config.categorias, detalhesConteudo: config.detalhesConteudo,
      config: config.parametros, iniciadoEm: new Date(), finalizadoEm: null, status: "andamento",
      leituras: [], observacoes: [{ em: new Date(), texto: "Início da queima." }],
    };
    setFornadas((fs) => [nova, ...fs]);
    setTela("forno");
    window.scrollTo(0, 0);
    notificar("Fornada iniciada! Acompanhamento em tempo real ativo.");
  }

  function atualizarTemperatura(valor, fornadaId) {
    setFornadas((fs) => fs.map((f) => f.id === fornadaId ? { ...f, leituras: [...f.leituras, { temp: valor, em: new Date() }] } : f));
    notificar("Temperatura real atualizada — gráfico e previsão recalculados.");
  }
  function adicionarObservacao(texto, fornadaId) {
    setFornadas((fs) => fs.map((f) => f.id === fornadaId ? { ...f, observacoes: [...f.observacoes, { em: new Date(), texto }] } : f));
    notificar("Observação adicionada.");
  }
  function finalizarFornada(fornadaId) {
    setFornadas((fs) => fs.map((f) => f.id === fornadaId ? { ...f, status: "finalizada", finalizadoEm: new Date() } : f));
    notificar("Fornada finalizada e salva no histórico.");
  }
  /* "Cancelar fornada" (2026-09-18, auditoria de autonomia) — o status
     "cancelada" já existia no enum/`STATUS_LABEL` desde sempre, mas
     NENHUMA ação do app o define — só dava pra Finalizar (queima
     concluída de verdade) ou substituir por Interrompida (ao iniciar
     outra no mesmo forno). Faltava um jeito de encerrar uma fornada
     começada por engano, sem fingir que ela "finalizou" de verdade.
     Mesmo padrão de `finalizarFornada` — só muda `status`, nunca apaga. */
  function cancelarFornada(fornadaId) {
    setFornadas((fs) => fs.map((f) => f.id === fornadaId ? { ...f, status: "cancelada", finalizadoEm: new Date() } : f));
    notificar("Fornada cancelada.");
  }
  /* Corrigir o conteúdo (categorias/detalhes) de uma fornada JÁ EM
     ANDAMENTO sem precisar duplicar — "Duplicar configuração" cria uma
     fornada NOVA, não serve pra corrigir um erro de digitação na atual.
     De propósito, só mexe em `categorias`/`detalhesConteudo`, nunca em
     `config` (temperatura/tempo) — mudar isso RETROATIVAMENTE
     recalcularia toda a curva de previsão já em andamento, categoria de
     mudança bem mais delicada que corrigir "o que tem dentro do forno". */
  function editarConteudoFornada(fornadaId, { categorias, detalhesConteudo }) {
    setFornadas((fs) => fs.map((f) => f.id === fornadaId ? { ...f, categorias, detalhesConteudo } : f));
    notificar("Conteúdo do forno atualizado.");
  }
  /* Avisos fixados (2026-09-18) — "qro implementar, uma seção de avisos,
     q eu coloque uma mensagem ou programa e vai ficar como um aviso fixo
     na tela inicial no topo, posso escolher pra mim como um lembrete, ou
     para os alunos". Lista vazia por padrão (não é dado real pré-
     existente, é uma feature nova). `destinatario: "admin" | "alunos"`
     só marca a intenção/categoria por enquanto — a Área do Aluno ainda
     não existe de verdade (ver PROGRESS.md, pausada nesta sessão), então
     um aviso "para os alunos" não tem pra onde ir além daqui ainda; a UI
     deixa isso explícito (etiqueta "Para os alunos" no próprio card do
     admin) em vez de fingir que já está sendo entregue a alguém. */
  const [avisos, setAvisos] = useState([]);
  const [modalAviso, setModalAviso] = useState(false);
  function criarAviso(texto, destinatario) {
    setAvisos((as) => [{ id: "av" + Date.now(), texto, destinatario, criadoEm: new Date() }, ...as]);
    notificar("Aviso fixado.");
    setModalAviso(false);
  }
  function removerAviso(id) {
    setAvisos((as) => as.filter((a) => a.id !== id));
  }

  function ir(t) { setTela(t); setMenuAberto(false); window.scrollTo(0, 0); }
  const [diaTurmaAlvo, setDiaTurmaAlvo] = useState("ter");
  function abrirDiaTurmas(diaId) { setDiaTurmaAlvo(diaId); ir("turmas"); }
  const [fornoAlvoDash, setFornoAlvoDash] = useState(FORNOS[0].id);
  function abrirForno(fornoId) { setFornoAlvoDash(fornoId); ir("forno"); }

  /* `vagasPorTurma` subiu de dentro de `Turmas` pra cá (2026-09-17) —
     mesmo padrão de `fornadas`/`oficinas`. Precisou subir porque duas
     features novas cruzam telas: clicar num aluno (em Turmas OU Alunos)
     pra ver a página de detalhe, e mover aluno entre turmas (que edita o
     roster de DUAS turmas ao mesmo tempo — Turmas só olhava a turma
     ativa). Pedido do Diego: "e ainda nao consigo clicar no aluno e ver
     a pagina dele. e qro poder arrastar um aluno de uma turma e passar
     para a outra, porem depois de soltar vai aparecer uma mensagem,
     vaga provisória... ou vai ser trasferido fixo". */
  const [vagasPorTurma, setVagasPorTurma] = useState(VAGAS_POR_TURMA_INICIAL);
  /* Lista de Alunos (tela "Alunos", busca/acordeão por turma) subiu de
     dentro do componente `Alunos` pro componente raiz (2026-09-18) — igual
     `vagasPorTurma` já tinha subido pra feature de mover aluno. Necessário
     porque `AlunoDetalhe`, que agora edita/exclui de verdade (pedido do
     Diego: "preciso ter as coisas editaveis tbm... excluir... editar o
     pacote, colocar se esta em dia ou nao, mudar a turma"), é renderizado
     aqui na raiz e precisa conseguir escrever nessa lista quando o aluno
     foi aberto a partir de Alunos (não de Turmas) — sem o lift, a edição
     só alcançaria o `useState` local de `Alunos`, que o componente raiz
     não tem como tocar. **`alunosLista` e `vagasPorTurma` continuam sendo
     DUAS fontes de dado separadas** (mesma pessoa pode ter uma linha em
     cada, não unificadas — decisão já registrada quando `AlunoDetalhe` foi
     criado, fora do escopo reabrir isso agora) — `salvarEdicaoAluno`/
     `excluirAlunoDetalhe` abaixo escrevem na fonte certa conforme de onde
     o aluno foi aberto (`aluno.turmaAtualId` presente = veio de Turmas =
     vagasPorTurma; ausente = veio de Alunos = alunosLista), sem tentar
     sincronizar as duas. */
  const [alunosLista, setAlunosLista] = useState(ALUNOS_REAIS);
  const [alunoSelecionado, setAlunoSelecionado] = useState(null);
  function abrirAlunoDetalhe(aluno, origemTela) {
    setAlunoSelecionado({ ...aluno, origemTela });
    ir("alunoDetalhe");
  }
  /* "Arrastar e soltar" de verdade não é um bom encaixe pro ambiente do
     artifact (sem lib de drag disponível — só react/lucide-react/
     recharts/tailwindcss — e HTML5 DnD nativo tem suporte fraco em touch,
     que é a prioridade do app). Implementado como ação por toque
     (botão "mover" em cada aluno → modal escolhe turma destino → escolhe
     provisório/fixo) que chega no mesmo resultado funcional do pedido.
     Registrado em CLAUDE.md pra não parecer decisão silenciosa. */
  function moverAluno(aluno, origemTurmaId, destinoTurmaId, tipo) {
    let movidoCalculado = null;
    setVagasPorTurma((vpt) => {
      const origem = (vpt[origemTurmaId] || []).map((v) =>
        v.numero === aluno.numero ? { numero: v.numero, nome: null } : v
      );
      const destino = vpt[destinoTurmaId] || [];
      const novoNumero = Math.max(0, ...destino.map((v) => v.numero)) + 1;
      const turmaOrigemFinal = tipo === "provisorio" ? (aluno.turmaOrigemId || origemTurmaId) : destinoTurmaId;
      const movido = { ...aluno, numero: novoNumero, turmaOrigemId: turmaOrigemFinal, provisorio: tipo === "provisorio" };
      movidoCalculado = movido;
      return { ...vpt, [origemTurmaId]: origem, [destinoTurmaId]: [...destino, movido] };
    });
    /* Se a pessoa movida é quem está aberta em AlunoDetalhe agora (tela de
       edição, ver `salvarEdicaoAluno`), atualiza `alunoSelecionado` junto
       — sem isso, a tela continuaria mostrando o `numero`/`turmaAtualId`
       antigos depois de "mudar a turma", e a PRÓXIMA edição (ex: pacote,
       logo em seguida) tentaria escrever na vaga errada (a antiga, já
       esvaziada). Fora do updater de `setVagasPorTurma` de propósito —
       chamar outro `setState` de dentro do updater funcional de um
       primeiro funciona, mas não é hábito seguro (o React pode invocar o
       updater mais de uma vez); capturar o valor calculado numa variável e
       aplicar depois, em sequência, evita essa categoria de problema.
       Não afeta o arraste normal em Turmas — lá `alunoSelecionado` é
       sempre `null` (não se arrasta e edita ao mesmo tempo), então essa
       checagem é um no-op nesse caso. */
    setAlunoSelecionado((sel) =>
      (sel && sel.turmaAtualId === origemTurmaId && sel.numero === aluno.numero)
        ? { ...sel, ...movidoCalculado, turmaAtualId: destinoTurmaId }
        : sel
    );
    const destinoInfo = turmaPorId(destinoTurmaId);
    notificar(
      tipo === "provisorio"
        ? `${aluno.nome}: vaga provisória em ${destinoInfo?.dia.split("-")[0]} só esta semana.`
        : `${aluno.nome}: transferido(a) fixo para ${destinoInfo?.dia.split("-")[0]}.`
    );
  }
  /* Remover aluno arrastando pra uma lateral da tela (2026-09-17) —
     "quando eu tiver segurando algum card e chegar proximo as laterias
     q elas fiquem destacadas para eu saber q tem uma ação ali". Some da
     turma sem entrar em nenhuma outra (diferente de `moverAluno`) — a
     vaga volta a ficar vazia/disponível, mesma representação de "sem
     nome" já usada no roster. Pede confirmação antes (ver `ModalRemover`
     dentro de `Turmas`), não remove só pelo gesto. */
  function removerAluno(aluno, turmaId) {
    setVagasPorTurma((vpt) => ({
      ...vpt,
      [turmaId]: (vpt[turmaId] || []).map((v) => (v.numero === aluno.numero ? { numero: v.numero, nome: null } : v)),
    }));
    notificar(`${aluno.nome} removido(a) da turma.`);
  }
  /* Edição de verdade em `AlunoDetalhe` (2026-09-18) — pedido do Diego,
     voltando pro app principal depois de começar a Área do Aluno: "preciso
     ter as coisas editaveis tbm... excluir... editar o pacote, colocar se
     esta em dia ou nao, mudar a turma". Um `form` só (turma + pacote +
     pagamento), salvos juntos — evita estados parciais estranhos (ex:
     trocar a turma sem também poder corrigir o pacote na mesma ida).
     `form = { turmaId, total, aula, pago }`; `pago` (booleano) é a entrada
     editável, `status` continua sendo DERIVADO dele com a mesma regra já
     documentada (CLAUDE.md §5: não pago tem prioridade sobre "ultima" —
     não inventa uma 4ª regra, só expõe a mesma como campo editável). */
  function salvarEdicaoAluno(aluno, form) {
    const status = !form.pago ? "pendente" : (form.aula === form.total ? "ultima" : "confirmado");
    const patchDados = { aula: form.aula, total: form.total, status };
    if (aluno.turmaAtualId) {
      if (form.turmaId !== aluno.turmaAtualId) {
        /* Mudar a turma pelo formulário é a MESMA operação que o
           arrastar-e-soltar já faz ("transferir fixo") — reaproveita
           `moverAluno` (que já cuida de esvaziar a vaga de origem, achar
           o próximo número livre no destino, e sincronizar
           `alunoSelecionado`) em vez de duplicar essa lógica aqui. O
           pacote/pagamento editados juntos já vão dentro do objeto —
           `moverAluno` espalha `{...aluno}` na vaga nova, então o patch
           viaja junto pro destino numa operação só. */
        moverAluno({ ...aluno, ...patchDados }, aluno.turmaAtualId, form.turmaId, "fixo");
      } else {
        setVagasPorTurma((vpt) => ({
          ...vpt,
          [aluno.turmaAtualId]: (vpt[aluno.turmaAtualId] || []).map((v) =>
            v.numero === aluno.numero ? { ...v, ...patchDados } : v
          ),
        }));
        setAlunoSelecionado((sel) => (sel ? { ...sel, ...patchDados } : sel));
      }
    } else {
      /* Veio da tela Alunos (`alunosLista`) — não tem vaga numerada, só um
         rótulo de turma em texto; "mudar a turma" aqui é só trocar esse
         rótulo, sem mexer em `vagasPorTurma` (as duas fontes continuam
         separadas, ver comentário em `alunosLista` acima). */
      const novoLabel = TURMA_ID_PARA_LABEL[form.turmaId] || aluno.turma;
      setAlunosLista((as) => as.map((a) => (a.nome === aluno.nome ? { ...a, ...patchDados, turma: novoLabel } : a)));
      setAlunoSelecionado((sel) => (sel ? { ...sel, ...patchDados, turma: novoLabel } : sel));
    }
    notificar(`${aluno.nome}: dados atualizados.`);
  }
  /* Excluir de verdade (não só "remover da turma", que deixa a vaga vazia
     mas a pessoa continua existindo em `alunosLista` se também estiver lá)
     — mesma ramificação por fonte de dado que `salvarEdicaoAluno`. Sempre
     navega de volta pra tela de origem depois, a página de detalhe não
     tem mais o que mostrar. */
  function excluirAlunoDetalhe(aluno) {
    if (aluno.turmaAtualId) removerAluno(aluno, aluno.turmaAtualId);
    else {
      setAlunosLista((as) => as.filter((a) => a.nome !== aluno.nome));
      notificar(`${aluno.nome} excluído(a).`);
    }
    setAlunoSelecionado(null);
    ir(aluno.origemTela === "alunos" ? "alunos" : "turmas");
  }
  /* Solicitações de verdade (2026-09-18) — pedido do Diego, auditoria de
     autonomia: "Aprovar"/"Recusar" só chamavam `notificar(...)`, a
     solicitação nunca saía da lista e aprovar não colocava ninguém em
     turma nenhuma. `SOLICITACOES_INICIAIS` subiu pra `useState` (mesmo
     padrão de `vagasPorTurma`/`alunosLista`/`fornadas`/`oficinas`).
     "Recusar" é simples (só tira da lista). "Aprovar" precisa de UM dado
     que a solicitação não carrega — o pacote (4/8/12) — então abre um
     modal pequeno (`ModalAprovarSolicitacao`, mesmo padrão visual de
     `ModalCadastrarAluno`) só pra confirmar isso antes de criar a vaga.
     **Simplificação deliberada**: os dois tipos de solicitação (pedido
     de vaga nova vs. "reposição") são tratados IGUAL — inserem a pessoa
     como vaga ocupada nova na turma pedida. Uma "reposição" de verdade
     seria uma transferência PROVISÓRIA de alguém que já é aluno de outra
     turma (mesmo mecanismo do `moverAluno`), mas o dado de solicitação
     só tem um nome solto, sem referência a uma vaga já existente pra
     mover — não dá pra inferir isso com segurança sem inventar uma
     ligação que não existe. Se isso importar na prática, é um pedido
     separado (a UI de aprovar precisaria oferecer "essa pessoa já é
     aluna? de qual turma?" como passo extra). */
  const [solicitacoes, setSolicitacoes] = useState(SOLICITACOES_INICIAIS);
  const [modalAprovarSolicitacao, setModalAprovarSolicitacao] = useState(null);
  function recusarSolicitacao(sol) {
    setSolicitacoes((ss) => ss.filter((s) => s.id !== sol.id));
    notificar(`Solicitação de ${sol.nome} recusada.`);
  }
  function aprovarSolicitacao(sol, total) {
    setVagasPorTurma((vpt) => {
      const destino = vpt[sol.turmaId] || [];
      const novoNumero = Math.max(0, ...destino.map((v) => v.numero)) + 1;
      const nova = { numero: novoNumero, nome: sol.nome, aula: 0, total, status: "confirmado", statusAula: "confirmado", presente: false, turmaOrigemId: sol.turmaId, provisorio: false };
      return { ...vpt, [sol.turmaId]: [...destino, nova] };
    });
    setSolicitacoes((ss) => ss.filter((s) => s.id !== sol.id));
    const turmaInfo = turmaPorId(sol.turmaId);
    notificar(`${sol.nome}: aprovado(a) em ${turmaInfo?.dia.split("-")[0]} · ${turmaInfo?.hora}.`);
    setModalAprovarSolicitacao(null);
  }
  /* Pagamentos editável (2026-09-18) — mesma auditoria de autonomia. A
     tela de Pagamentos não tinha setter nenhum (`const [pagamentos] =
     useState(...)`, sem par) — "marcar como pago" nem cabia ali. Como
     `pagamentosIniciais` passou a derivar de `vagasPorTurma` (state) em
     vez da constante fixa, marcar como pago é só atualizar o `status` da
     vaga de origem pra fora de "pendente" — o item some da lista de
     pendentes sozinho, sem precisar de um estado próprio de "quem já foi
     marcado". `id` do pagamento é sempre `${turmaId}-${numero}`
     (montado em `pagamentosIniciais`); `turmaId` em si já tem um hífen
     (ex: "ter-1830"), então separar pelo ÚLTIMO hífen (não o primeiro)
     é o jeito seguro de recuperar os dois pedaços. */
  function marcarPagamentoRecebido(pagamentoId) {
    const idx = pagamentoId.lastIndexOf("-");
    const turmaId = pagamentoId.slice(0, idx);
    const numero = Number(pagamentoId.slice(idx + 1));
    setVagasPorTurma((vpt) => ({
      ...vpt,
      [turmaId]: (vpt[turmaId] || []).map((v) =>
        v.numero === numero ? { ...v, status: v.aula === v.total ? "ultima" : "confirmado" } : v
      ),
    }));
    notificar("Pagamento marcado como recebido.");
  }

  return (
    <div className="flex min-h-screen w-full bg-[var(--cream)] text-[var(--ink)]" style={{ fontFamily: "var(--font-sans)" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=IBM+Plex+Mono:wght@500;600&family=Inter:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');
        :root {
          --cream: #F2F2EB; --cream-soft: #E7E4DA; --line: #DEDAD1;
          --ink: #3B3833; --ink-soft: #6B655C;
          --accent: #C2410C; --accent-hover: #9A3412; --accent-soft: #F3E1D6;
          --turma-sienna-rgb: 139 74 43; --turma-ardosia-rgb: 74 97 120;
          --turma-musgo-rgb: 95 107 58; --turma-cafe-rgb: 74 52 42;
          --font-sans: -apple-system, BlinkMacSystemFont, 'Inter', 'SF Pro Text', ui-sans-serif, system-ui, sans-serif;
          --font-mono: 'IBM Plex Mono', ui-monospace, monospace;
          --font-display: 'Bebas Neue', 'Space Grotesk', var(--font-sans);
        }
        @keyframes fadeUp{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}
        .animate-in{animation:fadeUp .2s ease-out both}
        /* Brilho ao redor do card do forno ativo, cor conforme a temperatura
           (--glow-rgb, definido inline por card via corIncandescente) —
           pedido do Diego (2026-09-17): "coloque envolta do card do forno,
           uma cor encandescente oscilando como se estivesse quente". */
        @keyframes brasaForno{
          0%,100%{box-shadow:0 0 0 1px rgb(var(--glow-rgb) / 0.5), 0 0 14px 1px rgb(var(--glow-rgb) / 0.32), 0 0 26px 3px rgb(var(--glow-rgb) / 0.18);}
          50%{box-shadow:0 0 0 1px rgb(var(--glow-rgb) / 0.85), 0 0 22px 4px rgb(var(--glow-rgb) / 0.55), 0 0 40px 9px rgb(var(--glow-rgb) / 0.34);}
        }
        .forno-brasa{animation:brasaForno 2.6s ease-in-out infinite;}
        /* Forno frio/desligado: mesma ideia, azul e bem mais discreto (raio e
           opacidade menores, oscilação mais lenta) — "o forno q estiver com
           uma temperatura mais baixa ou desligado, deixe ele com o volto em
           azul e com menos efeitos". */
        @keyframes brasaFornoFrio{
          0%,100%{box-shadow:0 0 0 1px rgb(var(--glow-rgb) / 0.4), 0 0 11px 0px rgb(var(--glow-rgb) / 0.22);}
          50%{box-shadow:0 0 0 1px rgb(var(--glow-rgb) / 0.6), 0 0 16px 1px rgb(var(--glow-rgb) / 0.32);}
        }
        .forno-fresco{animation:brasaFornoFrio 3.6s ease-in-out infinite;}
        /* Aviso fixado (2026-09-18) — "se for uma mensagem maior, q ela
           fique passando" (rolando tipo ticker, não cortando com "..."):
           o texto é duplicado no JSX (ver componente LinhaAviso) e a
           animação desloca exatamente 50% (a largura de UMA cópia),
           criando um loop contínuo sem pulo perceptível no fim. */
        @keyframes avisoPassando{from{transform:translateX(0);}to{transform:translateX(-50%);}}
        .aviso-passando{animation:avisoPassando 12s linear infinite;}
        /* Apple-ish default: soft rounding on every button/field unless a
           utility class (e.g. rounded-full on Toggle/Avatar) wins on specificity. */
        button, input, textarea, select { border-radius: 0.75rem; }
        /* Fase POLISH (2026-09-17): botões/links não tinham nenhum anel de
           foco visível ao navegar por teclado (Tab) — confirmado testando
           de verdade, não só suposição. Inputs já usam borda colorida como
           indicador (outline-none + focus:border-[var(--ink)], proposital,
           não mexido aqui). Anel visível, com a cor do sistema, só quando
           navegação é por teclado (:focus-visible não aparece em clique de
           mouse). */
        button:focus-visible, a:focus-visible, [role="checkbox"]:focus-visible, [tabindex]:focus-visible {
          outline: 2px solid var(--accent);
          outline-offset: 2px;
          border-radius: inherit;
        }
      `}</style>

      <ManchasFundo tela={tela} />

      <aside className="relative z-10 hidden md:flex md:w-32 md:shrink-0 md:flex-col md:border-r md:border-[var(--line)] md:bg-[var(--cream)] md:px-1.5 md:py-5">
        <div className="mb-6 flex justify-center px-1"><LogoMark className="text-2xl text-[var(--ink)]" /></div>
        <nav className="flex-1 space-y-0.5">
          {NAV.map((item) => (
            <button key={item.id} onClick={() => ir(item.id)} title={item.label} className={"relative flex w-full flex-col items-center gap-0.5 rounded-2xl px-1 py-2 text-[10px] font-medium leading-tight transition-colors " + ((tela === item.id || (item.id === "forno" && tela === "fornoNova") || (item.id === "oficinas" && tela === "oficinaDetalhe")) ? "bg-[var(--accent-soft)] text-[var(--accent)]" : "text-[var(--ink-soft)] hover:bg-white/60")}>
              <item.icon size={16} />
              <span className="truncate w-full text-center">{item.label}</span>
              {!!item.badge && <span className="absolute right-1 top-1 flex h-3.5 w-3.5 items-center justify-center bg-[var(--accent)] text-[9px] font-semibold text-white">{item.badge}</span>}
            </button>
          ))}
        </nav>
        <div className="mt-3 flex justify-center"><Avatar nome="Hanna" size={28} /></div>
      </aside>

      {menuAberto && (
        <div className="fixed inset-0 z-40 md:hidden">
          <div className="absolute inset-0 bg-black/30" onClick={() => setMenuAberto(false)} />
          <div className="absolute left-0 top-0 h-full w-64 rounded-r-[26px] border-y border-r border-white/70 bg-gradient-to-b from-[#FBF4E9]/90 to-[#F2E3D0]/70 p-4 shadow-[inset_0_1.5px_0_rgba(255,255,255,0.8),0_16px_32px_-10px_rgba(59,56,51,0.3)] backdrop-blur-2xl backdrop-saturate-150">
            <div className="mb-6 flex items-center justify-between"><LogoMark className="text-xl text-[var(--ink)]" /><button onClick={() => setMenuAberto(false)}><X size={20} /></button></div>
            <nav className="space-y-1">
              {NAV.map((item) => (
                <button key={item.id} onClick={() => ir(item.id)} className={"flex w-full items-center gap-2.5 rounded-2xl px-3 py-2.5 text-sm font-medium " + (tela === item.id ? "bg-[var(--accent-soft)] text-[var(--accent)]" : "text-[var(--ink-soft)]")}>
                  <item.icon size={17} />{item.label}
                  {!!item.badge && <span className="ml-auto bg-[var(--accent)] px-1.5 py-0.5 text-[11px] font-semibold text-white">{item.badge}</span>}
                </button>
              ))}
            </nav>
          </div>
        </div>
      )}

      <div className="min-w-0 flex-1 pb-20 md:pb-0">
        {/* Barra superior — passou por foto de mesclagem de argila →
           branco chapado → e agora pílula flutuante de vidro (2026-09-17,
           histórico completo em CLAUDE.md §6): "esse cabeçalho ainda nao
           ficou bom, deixe ele como uma pilula flutuante com os cantos
           arredondados com os efeitos nas bordas igual de vidro" —
           reabre a recusa de pílula de uma rodada atrás (era sobre a
           versão com foto escura; com fundo branco a leitura mudou).
           Mesma receita de vidro do resto do app (idêntica à nav
           inferior: `rounded-full` + gradiente branco translúcido +
           `backdrop-blur` + brilho interno + sombra de dois níveis), não
           uma variação nova. `fixed` (não relative) — flutua sobre o
           conteúdo que rola por baixo, como a nav inferior já faz; por
           isso o `<main>` ganhou `pt-24` extra no mobile (compensar a
           altura da pílula + a margem `top-3`), só nesse breakpoint
           (`md:pt-8` volta ao normal — cabeçalho é `md:hidden`). */}
        <header className="fixed inset-x-3 top-3 z-20 grid grid-cols-[1fr_auto_1fr] items-center rounded-full border border-white/70 bg-gradient-to-b from-white/80 to-white/50 px-4 py-5 shadow-[inset_0_1.5px_0_rgba(255,255,255,0.85),0_10px_28px_-6px_rgba(59,56,51,0.25)] backdrop-blur-2xl backdrop-saturate-150 md:hidden">
          <span />
          <LogoMark
            className="text-3xl justify-self-center"
            style={{
              backgroundImage: "linear-gradient(180deg, #0c0c0b, #000)",
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
              filter: "drop-shadow(0 0 0.6px rgba(255,255,255,0.85)) drop-shadow(0 0.5px 0.5px rgba(255,255,255,0.5))",
            }}
          />
          <Bell size={20} className="text-[var(--ink-soft)] justify-self-end" />
        </header>

        <main className="w-full px-4 pb-5 pt-24 md:px-6 md:py-8">
          {tela === "dashboard" && (
            <Dashboard
              ir={ir} fornadas={fornadas} vagasPorTurma={vagasPorTurma} onAbrirDia={abrirDiaTurmas} onAbrirOficinas={() => ir("oficinas")} onAbrirForno={abrirForno}
              solicitacoes={solicitacoes}
              onAprovarSolicitacao={(s) => setModalAprovarSolicitacao(s)}
              onRecusarSolicitacao={recusarSolicitacao}
              avisos={avisos}
              onNovoAviso={() => setModalAviso(true)}
              onRemoverAviso={removerAviso}
            />
          )}
          {tela === "turmas" && (
            <Turmas
              notificar={notificar}
              diaInicial={diaTurmaAlvo}
              vagasPorTurma={vagasPorTurma}
              setVagasPorTurma={setVagasPorTurma}
              onAbrirAluno={abrirAlunoDetalhe}
              onMoverAluno={moverAluno}
              onRemoverAluno={removerAluno}
              solicitacoes={solicitacoes}
              onAprovarSolicitacao={(s) => setModalAprovarSolicitacao(s)}
              onRecusarSolicitacao={recusarSolicitacao}
            />
          )}
          {tela === "alunos" && <Alunos alunos={alunosLista} setAlunos={setAlunosLista} onAbrirAluno={abrirAlunoDetalhe} />}
          {tela === "alunoDetalhe" && alunoSelecionado && (
            <AlunoDetalhe
              aluno={alunoSelecionado}
              onVoltar={() => ir(alunoSelecionado.origemTela === "alunos" ? "alunos" : "turmas")}
              onSalvarEdicao={salvarEdicaoAluno}
              onExcluir={excluirAlunoDetalhe}
            />
          )}
          {tela === "oficinas" && <Oficinas oficinas={oficinas} onAbrir={(id) => { setOficinaAbertaId(id); ir("oficinaDetalhe"); }} onNovaOficina={() => setModalOficina("nova")} />}
          {tela === "oficinaDetalhe" && (
            <OficinaDetalhe
              oficina={oficinas.find((o) => o.id === oficinaAbertaId)}
              notificar={notificar}
              onVoltar={() => ir("oficinas")}
              onEditarOficina={() => setModalOficina(oficinas.find((o) => o.id === oficinaAbertaId))}
              onCadastrarParticipante={(numero, dados) => {
                setOficinas((os) => os.map((o) => o.id !== oficinaAbertaId ? o : {
                  ...o, participantes: o.participantes.map((p) => p.numero === numero ? { numero, ...dados } : p),
                }));
                notificar("Participante cadastrado.");
              }}
              onRemoverParticipante={(numero) => {
                setOficinas((os) => os.map((o) => o.id !== oficinaAbertaId ? o : {
                  ...o, participantes: o.participantes.map((p) => p.numero === numero ? { numero, nome: null } : p),
                }));
                notificar("Participante removido.");
              }}
              onAtualizarStatusPecas={(novoStatus) => {
                setOficinas((os) => os.map((o) => o.id !== oficinaAbertaId ? o : { ...o, statusPecas: novoStatus }));
                notificar("Status das peças atualizado.");
              }}
            />
          )}
          {tela === "forno" && (
            <PainelForno
              fornadas={fornadas} notificar={notificar} fornoInicial={fornoAlvoDash}
              onNovaFornada={cliqueNovaFornada}
              onDuplicar={(f) => abrirNovaFornada(f, f.fornoId)}
              onAtualizarTemp={atualizarTemperatura}
              onAdicionarObs={adicionarObservacao}
              onFinalizar={finalizarFornada}
              onCancelar={cancelarFornada}
              onEditarConteudo={editarConteudoFornada}
            />
          )}
          {tela === "fornoNova" && (
            <NovaFornada rascunho={rascunho} onVoltar={() => ir("forno")} onIniciar={iniciarFornada} />
          )}
          {tela === "solicitacoes" && (
            <Solicitacoes
              solicitacoes={solicitacoes}
              onAprovarSolicitacao={(s) => setModalAprovarSolicitacao(s)}
              onRecusarSolicitacao={recusarSolicitacao}
            />
          )}
          {tela === "pagamentos" && <Pagamentos vagasPorTurma={vagasPorTurma} onMarcarPago={marcarPagamentoRecebido} />}
          {(tela === "relatorios" || tela === "config") && <EmBreve tela={tela} />}
        </main>
      </div>

      <nav className="fixed inset-x-3 bottom-3 z-30 flex items-center justify-around gap-1 rounded-full border border-white/70 bg-gradient-to-b from-white/70 to-white/35 px-2 py-2 shadow-[inset_0_1.5px_0_rgba(255,255,255,0.8),0_10px_24px_-6px_rgba(59,56,51,0.22)] backdrop-blur-2xl backdrop-saturate-150 md:hidden">
        {TABS_MOBILE.map((id) => {
          const item = NAV.find((n) => n.id === id);
          const ativoTab = tela === id || (id === "forno" && tela === "fornoNova");
          return (
            <button key={id} onClick={() => ir(id)} className={"flex flex-col items-center gap-0.5 rounded-full px-3 py-1.5 text-[11px] font-medium transition-colors " + (ativoTab ? ACCENT_SOLIDO : "text-[var(--ink-soft)]")}>
              <item.icon size={20} strokeWidth={ativoTab ? 2.4 : 1.8} />{item.label}
            </button>
          );
        })}
        <button onClick={() => setMenuAberto(true)} className="flex flex-col items-center gap-0.5 rounded-full px-3 py-1.5 text-[11px] font-medium text-[var(--ink-soft)]"><Menu size={20} />Mais</button>
      </nav>

      {toast && <div className="fixed bottom-24 left-1/2 z-50 -translate-x-1/2 bg-[var(--ink)] px-4 py-2.5 text-sm text-[var(--cream)] shadow-lg md:bottom-6">{toast}</div>}

      {modalConflito && (
        <Modal onClose={() => setModalConflito(null)}>
          <h3 className="mb-2 text-base font-semibold">{FORNOS.find((f) => f.id === modalConflito)?.nome} já tem uma fornada em andamento</h3>
          <p className="mb-5 text-sm leading-relaxed text-[var(--ink-soft)]">
            Esse forno já está sendo acompanhado. Ao iniciar uma nova fornada nele, a atual será encerrada automaticamente e salva no histórico. Nenhuma informação será perdida. Deseja continuar?
          </p>
          <div className="flex gap-2">
            <button onClick={() => setModalConflito(null)} className="flex-1 border border-[var(--line)] py-2.5 text-sm font-medium text-[var(--ink)] hover:bg-[var(--cream)]">Cancelar</button>
            <button onClick={confirmarSalvarEIniciarNova} className={"flex-1 py-2.5 text-sm font-medium " + ACCENT_SOLIDO}>Salvar e criar nova</button>
          </div>
        </Modal>
      )}

      {modalAprovarSolicitacao && (
        <ModalAprovarSolicitacao
          solicitacao={modalAprovarSolicitacao}
          onClose={() => setModalAprovarSolicitacao(null)}
          onConfirmar={(total) => aprovarSolicitacao(modalAprovarSolicitacao, total)}
        />
      )}

      {modalOficina && (
        <ModalOficina
          oficina={modalOficina === "nova" ? null : modalOficina}
          onClose={() => setModalOficina(null)}
          onSalvar={(dados) => modalOficina === "nova" ? criarOficina(dados) : editarOficina(modalOficina.id, dados)}
        />
      )}

      {modalAviso && (
        <ModalNovoAviso onClose={() => setModalAviso(false)} onSalvar={criarAviso} />
      )}
    </div>
  );
}

/* Avisos fixados no topo do Dashboard (2026-09-18) — ver `avisos`/
   `criarAviso`/`removerAviso` no componente raiz pro histórico completo
   do pedido. **Três rodadas de redesenho no mesmo dia**:
   1ª: de `Card` normal (cantos arredondados, vidro) pra faixa cheia sem
   bordas ("esse aviso eu qria algo mais como um banner suspenso iguais
   aqueles de site q fica fixo colado sem bordas") — `-mx-4 md:-mx-6`
   (cancela o padding lateral do `<main>`, mesmo valor do `className`
   dele no componente raiz) pra encostar nas bordas da tela.
   2ª: a 1ª versão usava fundo sólido escuro + ícone de sino + botões — o
   Diego mandou um print de referência (banner de site real: faixa FINA,
   cor clara/terrosa, texto normal sublinhado, sem ícone) com "qro algo
   proximo a isso". Fundo virou `rgbCor("sienna", 0.12)`, texto sublinhado
   sem negrito.
   3ª: "esta bom assim, porem so deixe a mensagem sem esse 'lembrete'...
   para diferencias se e para mim ou para os alunos, mude a cor, deixe
   preto para os alunos e vermelho pra mim" + "e as mensagem sempre em
   maiusculo" — tira o texto de categoria por extenso (a cor sozinha já
   diferencia: `--ink` pros alunos, `rose-600` pra admin), `uppercase`
   via CSS (não mexe no dado digitado, só a exibição — mesmo padrão já
   usado nos títulos de página com Bebas Neue). "Se for uma mensagem
   maior, q ela fique passando" — `LinhaAviso` abaixo mede
   `scrollWidth` vs largura do container e só liga a animação de ticker
   (`.aviso-passando`, ver `<style>` do componente raiz) quando o texto
   de fato não cabe; texto duplicado no DOM (uma cópia visível +
   `aria-hidden`) pra o loop de -50% fechar sem pulo. */
function LinhaAviso({ texto, cor }) {
  const containerRef = useRef(null);
  const textoRef = useRef(null);
  const [passando, setPassando] = useState(false);
  useEffect(() => {
    function medir() {
      if (containerRef.current && textoRef.current) {
        setPassando(textoRef.current.scrollWidth > containerRef.current.clientWidth);
      }
    }
    medir();
    window.addEventListener("resize", medir);
    return () => window.removeEventListener("resize", medir);
  }, [texto]);
  return (
    <div ref={containerRef} className={"min-w-0 flex-1 overflow-hidden " + (passando ? "" : "flex justify-center")}>
      <div className={"flex w-max whitespace-nowrap " + (passando ? "aviso-passando" : "")}>
        <span ref={textoRef} className={"shrink-0 pr-10 text-xs font-medium uppercase tracking-wide underline underline-offset-2 " + cor}>{texto}</span>
        {passando && <span aria-hidden="true" className={"shrink-0 pr-10 text-xs font-medium uppercase tracking-wide underline underline-offset-2 " + cor}>{texto}</span>}
      </div>
    </div>
  );
}
function AvisosCard({ avisos, onNovoAviso, onRemover }) {
  const estiloFaixa = { background: rgbCor("sienna", 0.12) };
  /* `rounded-none` explícito nos `<button>` abaixo — sem isso, a regra
     CSS global de baixa especificidade (`button { border-radius: 0.75rem
     }`, ver CLAUDE.md §6.1) arredonda os cantos por cima do que a faixa
     pede. `w-full` também explícito — `<button>` não estica pra ocupar a
     largura toda sozinho como um `<div>` faria, precisa pedir. */
  if (avisos.length === 0) {
    return (
      <button onClick={onNovoAviso} className="-mx-4 flex w-full items-center justify-center rounded-none px-4 py-2 text-center text-xs font-medium uppercase tracking-wide text-[var(--ink)] underline underline-offset-2 md:-mx-6 md:px-6" style={estiloFaixa}>
        Fixar um aviso no topo
      </button>
    );
  }
  return (
    <div className="-mx-4 md:-mx-6">
      {avisos.map((a) => (
        <div key={a.id} className="flex items-center justify-center gap-2 px-4 py-2 md:px-6" style={estiloFaixa}>
          <LinhaAviso texto={a.texto} cor={a.destinatario === "alunos" ? "text-[var(--ink)]" : "text-rose-600"} />
          <button onClick={() => onRemover(a.id)} aria-label="Remover aviso" className="shrink-0 rounded-none text-[var(--ink-soft)] hover:text-[var(--ink)]"><X size={13} /></button>
        </div>
      ))}
      <button onClick={onNovoAviso} className="flex w-full items-center justify-center rounded-none px-4 py-1.5 text-center text-[11px] font-medium uppercase tracking-wide text-[var(--ink-soft)] underline underline-offset-2 hover:text-[var(--ink)] md:px-6" style={estiloFaixa}>
        + Novo aviso
      </button>
    </div>
  );
}
function ModalNovoAviso({ onClose, onSalvar }) {
  const [texto, setTexto] = useState("");
  const [destinatario, setDestinatario] = useState("admin");
  return (
    <Modal onClose={onClose}>
      <h3 className="mb-3 text-base font-semibold">Novo aviso</h3>
      <form onSubmit={(e) => { e.preventDefault(); if (!texto.trim()) return; onSalvar(texto.trim(), destinatario); }}>
        <label className="mb-1 block text-xs font-medium text-[var(--ink-soft)]">Mensagem</label>
        <textarea autoFocus value={texto} onChange={(e) => setTexto(e.target.value)} rows={3} className="mb-3 w-full border border-[var(--line)] px-3 py-2.5 text-sm outline-none focus:border-[var(--ink)]" placeholder="Ex: Comprar mais esmalte azul." />
        <label className="mb-1 block text-xs font-medium text-[var(--ink-soft)]">Para quem</label>
        <div className="mb-4 flex gap-2">
          {[["admin", "Lembrete pra mim"], ["alunos", "Para os alunos"]].map(([id, label]) => (
            <button type="button" key={id} onClick={() => setDestinatario(id)} className={"flex-1 border px-3 py-2.5 text-xs font-medium " + (destinatario === id ? "border-[var(--ink)] bg-[var(--cream-soft)] text-[var(--ink)]" : "border-[var(--line)] text-[var(--ink-soft)]")}>{label}</button>
          ))}
        </div>
        {destinatario === "alunos" && (
          <p className="mb-4 text-xs text-[var(--ink-soft)]">A Área do Aluno ainda não existe de verdade no app — por enquanto isso fica visível aqui, marcado como "Para os alunos".</p>
        )}
        <div className="flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 border border-[var(--line)] py-2.5 text-sm font-medium text-[var(--ink)]">Cancelar</button>
          <button type="submit" className={"flex-1 py-2.5 text-sm font-medium " + ACCENT_SOLIDO}>Fixar aviso</button>
        </div>
      </form>
    </Modal>
  );
}

